package com.kitchenai.recipe; import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import com.kitchenai.ai.*; import com.kitchenai.cooking.*; import com.kitchenai.common.ApiException; import com.kitchenai.gamification.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class RecipeController { private final RecipeRepository recipes;private final CookingSessionRepository sessions;private final RecipeGenerationService ai;private final ObjectMapper json;private final UserProgressRepository progress; public RecipeController(RecipeRepository r,CookingSessionRepository s,RecipeGenerationService a,ObjectMapper j,UserProgressRepository p){recipes=r;sessions=s;ai=a;json=j;progress=p;}
 public record GenerateRequest(@NotBlank String desiredFood,String conditions,String dietaryRestrictions,String availableIngredients,@Min(1) @Max(30) Integer servings){} public record SessionRequest(UUID recipeId,String desiredOutcome){}
 @PostMapping("/recipes/generate") public RecipeView generate(@Valid @RequestBody GenerateRequest r,@AuthenticationPrincipal UUID id){var x=ai.generate(new RecipeGenerationService.RecipeRequest(r.desiredFood(),r.conditions(),r.dietaryRestrictions(),r.availableIngredients(),r.servings()));try{var saved=recipes.save(new Recipe(id,x.title(),x.description(),x.productType(),x.servings(),x.preparationTime(),x.cookingTime(),json.writeValueAsString(x.ingredients()),json.writeValueAsString(x.stages())));return view(saved);}catch(JsonProcessingException e){throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR,"Recipe serialization failed");}}
 @GetMapping("/recipes") public List<RecipeView> list(@AuthenticationPrincipal UUID id){return recipes.findTop10ByUserIdOrderByCreatedAtDesc(id).stream().map(this::view).toList();} @GetMapping("/recipes/{id}") public RecipeView one(@PathVariable UUID id,@AuthenticationPrincipal UUID user){return view(owned(id,user));}
 @PostMapping("/cooking-sessions") public CookingSession start(@Valid @RequestBody SessionRequest r,@AuthenticationPrincipal UUID user){if(r.recipeId()!=null)owned(r.recipeId(),user);return sessions.save(new CookingSession(user,r.recipeId(),r.recipeId()==null?"RECOVERY":"RECIPE",r.desiredOutcome()));}
 @GetMapping("/cooking-sessions") public List<CookingSession> allSessions(@AuthenticationPrincipal UUID user){return sessions.findTop10ByUserIdOrderByStartedAtDesc(user);} @GetMapping("/cooking-sessions/{id}") public CookingSession detail(@PathVariable UUID id,@AuthenticationPrincipal UUID user){return session(id,user);}
 @PostMapping("/cooking-sessions/{id}/complete") public Map<String,Object> complete(@PathVariable UUID id,@AuthenticationPrincipal UUID user){var s=session(id,user);s.complete();sessions.save(s);var p=progress.findByUserId(user).orElseGet(()->progress.save(new UserProgress(user)));p.add(10);progress.save(p);return Map.of("status","COMPLETED","xpAwarded",10);} @PostMapping("/cooking-sessions/{id}/abandon") public Map<String,Object> abandon(@PathVariable UUID id,@AuthenticationPrincipal UUID user){var s=session(id,user);s.abandon();sessions.save(s);return Map.of("status","ABANDONED");}
 private Recipe owned(UUID id,UUID u){return recipes.findById(id).filter(x->x.getUserId().equals(u)).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Recipe not found"));} private CookingSession session(UUID id,UUID u){return sessions.findById(id).filter(x->x.getUserId().equals(u)).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Session not found"));} private RecipeView view(Recipe r){return new RecipeView(r.getId(),r.getTitle(),r.getDescription(),r.getProductType(),r.getServings(),r.getPreparationTime(),r.getCookingTime(),r.getIngredientsJson(),r.getStagesJson());} public record RecipeView(UUID id,String title,String description,String productType,int servings,int preparationTime,int cookingTime,String ingredients,String stages){} }
